import java.util.*; public class Q06_LibraryBookAuthor{static class Author{String n,e,g;Author(String n,String e,String g){this.n=n;this.e=e;this.g=g;}}static class Book{String t;double p;Author a;Book(String t,double p,Author a){this.t=t;this.p=p;this.a=a;}public String toString(){return "Book: "+t+"\nPrice: "+p+"\nAuthor: "+a.n+" ("+a.g+"), Email: "+a.e;}}public static void main(String[]x){String[]p=new Scanner(System.in).nextLine().split(",",5);System.out.println(new Book(p[0],Double.parseDouble(p[1]),new Author(p[2],p[3],p[4])));}}
